import{_ as e,W as a,X as n,a2 as s}from"./framework-6a3aa88c.js";const i={},d=s(`<h1 id="第九课-service-稳定访问入口" tabindex="-1"><a class="header-anchor" href="#第九课-service-稳定访问入口" aria-hidden="true">#</a> 第九课：Service 稳定访问入口</h1><h2 id="这节课只解决一个问题" tabindex="-1"><a class="header-anchor" href="#这节课只解决一个问题" aria-hidden="true">#</a> 这节课只解决一个问题</h2><p>Deployment 管理的 Pod 随时可能被删除和替换，Pod 名称和 IP 都可能变化。调用方应该怎样稳定访问应用？</p><p>答案是：在 Pod 前面增加 Service。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>调用方
  ↓
Service：稳定入口
  ↓
当前可用的 Pod
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="一、为什么不能直接记住-pod-ip" tabindex="-1"><a class="header-anchor" href="#一、为什么不能直接记住-pod-ip" aria-hidden="true">#</a> 一、为什么不能直接记住 Pod IP</h2><p>Pod 运行后会获得一个 IP：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Pod A → 10.1.0.31
Pod B → 10.1.0.32
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>但上一课已经看到，更新、扩缩容和故障恢复都会替换 Pod。</p><p>例如 Pod A 被删除后，新 Pod 可能变成：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>旧 Pod A → 10.1.0.31，已删除
新 Pod C → 10.1.0.35，新建
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>如果其他应用把 <code>10.1.0.31</code> 写死，Pod 替换后就找不到 Nginx。</p><p>Pod IP 应当被看作运行期间的临时地址，不适合作为长期服务入口。</p><h2 id="二、把-service-理解成前台总机" tabindex="-1"><a class="header-anchor" href="#二、把-service-理解成前台总机" aria-hidden="true">#</a> 二、把 Service 理解成前台总机</h2><p>公司员工会更换座位和分机，但客户只需要拨打公司总机。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>客户
  ↓
公司总机：稳定号码
  ├── 员工 A：当前分机
  └── 员工 B：当前分机
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对应到 Kubernetes：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>调用方
  ↓
Service：稳定入口
  ├── Pod A：当前 IP
  └── Pod B：当前 IP
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Pod 被替换后，Service 后面的 Pod 清单会更新，而调用方继续访问同一个 Service。</p><h2 id="三、准备两个-nginx-pod" tabindex="-1"><a class="header-anchor" href="#三、准备两个-nginx-pod" aria-hidden="true">#</a> 三、准备两个 Nginx Pod</h2><p>Deployment 文件：<code>labs/07-Service/01-nginx-deployment.yaml</code></p><p>在线阅读时，请先保存下面的完整 YAML：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">apiVersion</span><span class="token punctuation">:</span> apps/v1
<span class="token key atrule">kind</span><span class="token punctuation">:</span> Deployment
<span class="token key atrule">metadata</span><span class="token punctuation">:</span>
  <span class="token key atrule">name</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall<span class="token punctuation">-</span>web
  <span class="token key atrule">labels</span><span class="token punctuation">:</span>
    <span class="token key atrule">app</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall
    <span class="token key atrule">tier</span><span class="token punctuation">:</span> frontend
    <span class="token key atrule">environment</span><span class="token punctuation">:</span> development
<span class="token key atrule">spec</span><span class="token punctuation">:</span>
  <span class="token key atrule">replicas</span><span class="token punctuation">:</span> <span class="token number">2</span>
  <span class="token key atrule">selector</span><span class="token punctuation">:</span>
    <span class="token key atrule">matchLabels</span><span class="token punctuation">:</span>
      <span class="token key atrule">app</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall
      <span class="token key atrule">tier</span><span class="token punctuation">:</span> frontend
  <span class="token key atrule">template</span><span class="token punctuation">:</span>
    <span class="token key atrule">metadata</span><span class="token punctuation">:</span>
      <span class="token key atrule">labels</span><span class="token punctuation">:</span>
        <span class="token key atrule">app</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall
        <span class="token key atrule">tier</span><span class="token punctuation">:</span> frontend
        <span class="token key atrule">environment</span><span class="token punctuation">:</span> development
    <span class="token key atrule">spec</span><span class="token punctuation">:</span>
      <span class="token key atrule">containers</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> nginx
          <span class="token key atrule">image</span><span class="token punctuation">:</span> nginx<span class="token punctuation">:</span><span class="token number">1.27</span>
          <span class="token key atrule">ports</span><span class="token punctuation">:</span>
            <span class="token punctuation">-</span> <span class="token key atrule">containerPort</span><span class="token punctuation">:</span> <span class="token number">80</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果目录不存在，先执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">mkdir</span> <span class="token parameter variable">-p</span> labs/07-Service
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>它会创建两个带相同 Label 的 Nginx Pod：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">replicas</span><span class="token punctuation">:</span> <span class="token number">2</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">labels</span><span class="token punctuation">:</span>
  <span class="token key atrule">app</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>进入项目目录：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">cd</span> /Users/qintianpeng/2026/code/k8s
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>创建 Deployment：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl apply <span class="token parameter variable">-f</span> labs/07-Service/01-nginx-deployment.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>等待完成：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl rollout status deployment/qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>查看 Pod 名称和 IP：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pods <span class="token parameter variable">-l</span> <span class="token string">&#39;app=qingyun-mall,tier=frontend&#39;</span> <span class="token parameter variable">-o</span> wide
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>记录当前两个 Pod 的 <code>NAME</code> 和 <code>IP</code>。实际名称和 IP 以你的输出为准。</p><h2 id="四、创建-service" tabindex="-1"><a class="header-anchor" href="#四、创建-service" aria-hidden="true">#</a> 四、创建 Service</h2><p>Service 文件：<code>labs/07-Service/02-nginx-service.yaml</code></p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">apiVersion</span><span class="token punctuation">:</span> v1
<span class="token key atrule">kind</span><span class="token punctuation">:</span> Service
<span class="token key atrule">metadata</span><span class="token punctuation">:</span>
  <span class="token key atrule">name</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall<span class="token punctuation">-</span>web
  <span class="token key atrule">labels</span><span class="token punctuation">:</span>
    <span class="token key atrule">app</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall
    <span class="token key atrule">tier</span><span class="token punctuation">:</span> frontend
    <span class="token key atrule">environment</span><span class="token punctuation">:</span> development
<span class="token key atrule">spec</span><span class="token punctuation">:</span>
  <span class="token key atrule">selector</span><span class="token punctuation">:</span>
    <span class="token key atrule">app</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall
    <span class="token key atrule">tier</span><span class="token punctuation">:</span> frontend
  <span class="token key atrule">ports</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> http
      <span class="token key atrule">port</span><span class="token punctuation">:</span> <span class="token number">80</span>
      <span class="token key atrule">targetPort</span><span class="token punctuation">:</span> <span class="token number">80</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在线阅读时，请把上面的完整 YAML 保存为：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>labs/07-Service/02-nginx-service.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>创建：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl apply <span class="token parameter variable">-f</span> labs/07-Service/02-nginx-service.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>正常输出：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>service/qingyun-mall-web created
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="五、理解-service-yaml" tabindex="-1"><a class="header-anchor" href="#五、理解-service-yaml" aria-hidden="true">#</a> 五、理解 Service YAML</h2><h3 id="kind-service" tabindex="-1"><a class="header-anchor" href="#kind-service" aria-hidden="true">#</a> <code>kind: Service</code></h3><p>表示创建一个 Service 对象：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">kind</span><span class="token punctuation">:</span> Service
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="selector-选择哪些-pod" tabindex="-1"><a class="header-anchor" href="#selector-选择哪些-pod" aria-hidden="true">#</a> <code>selector</code>：选择哪些 Pod</h3><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">selector</span><span class="token punctuation">:</span>
  <span class="token key atrule">app</span><span class="token punctuation">:</span> qingyun<span class="token punctuation">-</span>mall
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>意思是：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>寻找带有 app=qingyun-mall 标签的 Pod
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Deployment 创建的 Pod 恰好带有这个 Label：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Pod A [app=qingyun-mall]
Pod B [app=qingyun-mall]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>所以它们会成为 Service 后面的目标。</p><p>Service 不通过 Pod 名称建立关系，而是通过 Label 选择一组 Pod。</p><h3 id="port-和-targetport" tabindex="-1"><a class="header-anchor" href="#port-和-targetport" aria-hidden="true">#</a> <code>port</code> 和 <code>targetPort</code></h3><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">port</span><span class="token punctuation">:</span> <span class="token number">80</span>
<span class="token key atrule">targetPort</span><span class="token punctuation">:</span> <span class="token number">80</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>先这样理解：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>访问 Service 的 80 端口
          ↓
转到 Pod 的 80 端口
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>port</code>：Service 对调用方提供的端口；</li><li><code>targetPort</code>：Pod 中应用实际接收请求的端口。</li></ul><p>这次两边都使用 80，所以数字相同，但它们代表两个不同位置。</p><h2 id="六、查看-service" tabindex="-1"><a class="header-anchor" href="#六、查看-service" aria-hidden="true">#</a> 六、查看 Service</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get <span class="token function">service</span> qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>可能看到：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>NAME              TYPE        CLUSTER-IP     PORT(S)
qingyun-mall-web         ClusterIP   10.96.x.x      80/TCP
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>现在只看三项：</p><h3 id="type-clusterip" tabindex="-1"><a class="header-anchor" href="#type-clusterip" aria-hidden="true">#</a> <code>TYPE: ClusterIP</code></h3><p>这是默认 Service 类型，表示它主要提供集群内部访问入口。</p><p>你的 Mac 浏览器不能把这个 ClusterIP 当普通公网地址直接访问，所以本课仍使用 <code>port-forward</code> 做本地验证。</p><h3 id="cluster-ip" tabindex="-1"><a class="header-anchor" href="#cluster-ip" aria-hidden="true">#</a> <code>CLUSTER-IP</code></h3><p>这是 Service 在集群内部的稳定虚拟地址。只要 Service 没有被删除重建，它通常保持不变。</p><h3 id="port-s-80-tcp" tabindex="-1"><a class="header-anchor" href="#port-s-80-tcp" aria-hidden="true">#</a> <code>PORT(S): 80/TCP</code></h3><p>表示 Service 使用 TCP 80 端口。</p><h2 id="七、查看-service-当前指向谁" tabindex="-1"><a class="header-anchor" href="#七、查看-service-当前指向谁" aria-hidden="true">#</a> 七、查看 Service 当前指向谁</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl describe <span class="token function">service</span> qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>重点看：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Selector:  app=qingyun-mall
Endpoints: 10.1.0.x:80,10.1.0.y:80
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>Endpoints</code> 可以先理解成 Service 当前找到的 Pod 地址清单。</p><p>它应该对应前面两个 Nginx Pod 的 IP 和 80 端口：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Service qingyun-mall-web:80
├── Pod A IP:80
└── Pod B IP:80
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果 <code>Endpoints</code> 显示为空，通常要先检查 Service selector 与 Pod Label 是否一致。</p><h2 id="八、通过-service-访问-nginx" tabindex="-1"><a class="header-anchor" href="#八、通过-service-访问-nginx" aria-hidden="true">#</a> 八、通过 Service 访问 Nginx</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl port-forward service/qingyun-mall-web <span class="token number">18080</span>:80
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>等待出现：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Forwarding from 127.0.0.1:18080 -&gt; 80
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>再用浏览器访问：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>http://127.0.0.1:18080
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>看到 <code>Welcome to nginx!</code> 表示：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>浏览器
  ↓ Mac 18080
port-forward
  ↓ Service 80
Service 选择的 Nginx Pod
  ↓
Nginx 欢迎页面
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>完成后按 <code>Control + C</code> 停止转发。</p><p>注意：port-forward 仍然只是本地调试通道。本课要验证的是 Service 能找到 Pod，不把 port-forward 当成生产入口。</p><h2 id="九、记录-service-ip" tabindex="-1"><a class="header-anchor" href="#九、记录-service-ip" aria-hidden="true">#</a> 九、记录 Service IP</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get <span class="token function">service</span> qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>记录 <code>CLUSTER-IP</code>，稍后删除一个 Pod 后再次对比。</p><h2 id="十、删除一个-pod" tabindex="-1"><a class="header-anchor" href="#十、删除一个-pod" aria-hidden="true">#</a> 十、删除一个 Pod</h2><p>先列出 Pod：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pods <span class="token parameter variable">-l</span> <span class="token string">&#39;app=qingyun-mall,tier=frontend&#39;</span> <span class="token parameter variable">-o</span> wide
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>复制任意一个 Pod 的完整名称，然后执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl delete pod <span class="token operator">&lt;</span>复制的Pod名称<span class="token operator">&gt;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>不要把尖括号原样输入。例如：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl delete pod qingyun-mall-web-xxxxxxxxxx-abcde
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Deployment 会补充一个新的 Pod。</p><p>持续观察：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get pods <span class="token parameter variable">-l</span> <span class="token string">&#39;app=qingyun-mall,tier=frontend&#39;</span> <span class="token parameter variable">-o</span> wide <span class="token parameter variable">-w</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>等到重新有两个 <code>1/1 Running</code> Pod 后按 <code>Control + C</code>。</p><p>对比会发现：</p><ul><li>被删除 Pod 的名称消失；</li><li>新 Pod 名称不同；</li><li>新 Pod IP 通常也不同。</li></ul><h2 id="十一、service-不需要手工修改" tabindex="-1"><a class="header-anchor" href="#十一、service-不需要手工修改" aria-hidden="true">#</a> 十一、Service 不需要手工修改</h2><p>再次查看 Service：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get <span class="token function">service</span> qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>CLUSTER-IP</code> 应与删除 Pod 前相同。</p><p>再看详细信息：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl describe <span class="token function">service</span> qingyun-mall-web
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>Endpoints</code> 应自动移除旧 Pod IP，并加入新 Pod IP：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>替换前：
Service → Pod A IP、Pod B IP

Pod A 被删除，新 Pod C 出现

替换后：
Service → Pod B IP、Pod C IP
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>整个过程中，我们没有手工编辑 Service。</p><p>原因是 Service 按 Label 寻找当前 Pod，而不是写死 Pod 名称或 IP。</p><h2 id="十二、再次通过-service-访问" tabindex="-1"><a class="header-anchor" href="#十二、再次通过-service-访问" aria-hidden="true">#</a> 十二、再次通过 Service 访问</h2><p>执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl port-forward service/qingyun-mall-web <span class="token number">18080</span>:80
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>看到 <code>Forwarding</code> 后，再访问：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>http://127.0.0.1:18080
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>仍应看到 Nginx 欢迎页面。完成后按 <code>Control + C</code>。</p><p>注意，我们是等新 Pod 稳定后重新建立 port-forward。这一实验不能用来证明 port-forward 本身具有持续故障切换能力；它只验证替换后 Service 仍有正确后端。</p><h2 id="十三、service-和-deployment-各管什么" tabindex="-1"><a class="header-anchor" href="#十三、service-和-deployment-各管什么" aria-hidden="true">#</a> 十三、Service 和 Deployment 各管什么</h2><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Deployment
负责：Pod 要有几个、使用什么模板

Service
负责：为一组 Pod 提供稳定访问入口
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>组合起来：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>             Deployment
                 ↓ 创建和替换
调用方 → Service → Pod A
                 → Pod B
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Deployment 解决“应用实例怎么长期存在”，Service 解决“调用方怎么找到不断变化的实例”。</p><h2 id="十四、service-会启动-nginx-吗" tabindex="-1"><a class="header-anchor" href="#十四、service-会启动-nginx-吗" aria-hidden="true">#</a> 十四、Service 会启动 Nginx 吗</h2><p>不会。</p><p>Service 不运行应用，也不创建 Pod。它只根据 selector 找到已有 Pod，并提供访问入口。</p><p>因此如果 Deployment 被删除，只留下 Service：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>Service 对象仍可能存在
但 Endpoints 为空
请求没有后端可以处理
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="十五、清理顺序" tabindex="-1"><a class="header-anchor" href="#十五、清理顺序" aria-hidden="true">#</a> 十五、清理顺序</h2><p>先删除 Service：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl delete <span class="token parameter variable">-f</span> labs/07-Service/02-nginx-service.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>再删除 Deployment：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl delete <span class="token parameter variable">-f</span> labs/07-Service/01-nginx-deployment.yaml
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>最后确认：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>kubectl get deployment,service,pod <span class="token parameter variable">-l</span> <span class="token string">&#39;app=qingyun-mall,tier=frontend&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>最终没有课程资源，表示清理完成。</p><h2 id="十六、问题与直接回答" tabindex="-1"><a class="header-anchor" href="#十六、问题与直接回答" aria-hidden="true">#</a> 十六、问题与直接回答</h2><h3 id="为什么不能让其他应用直接记住-pod-ip" tabindex="-1"><a class="header-anchor" href="#为什么不能让其他应用直接记住-pod-ip" aria-hidden="true">#</a> 为什么不能让其他应用直接记住 Pod IP？</h3><p>因为 Pod 被更新、扩缩容或故障替换后，名称和 IP 都可能变化。</p><h3 id="service-自己运行-nginx-吗" tabindex="-1"><a class="header-anchor" href="#service-自己运行-nginx-吗" aria-hidden="true">#</a> Service 自己运行 Nginx 吗？</h3><p>不运行。Service 只是入口，真正处理请求的是后面的 Pod。</p><h3 id="service-怎样找到-pod" tabindex="-1"><a class="header-anchor" href="#service-怎样找到-pod" aria-hidden="true">#</a> Service 怎样找到 Pod？</h3><p>通过 selector 匹配 Pod 的 Label。本课匹配条件是 <code>app=qingyun-mall</code>。</p><h3 id="port-和-targetport-有什么区别" tabindex="-1"><a class="header-anchor" href="#port-和-targetport-有什么区别" aria-hidden="true">#</a> <code>port</code> 和 <code>targetPort</code> 有什么区别？</h3><p><code>port</code> 是 Service 对调用方提供的端口，<code>targetPort</code> 是 Pod 中应用接收请求的端口。</p><h3 id="clusterip-能直接从互联网访问吗" tabindex="-1"><a class="header-anchor" href="#clusterip-能直接从互联网访问吗" aria-hidden="true">#</a> <code>ClusterIP</code> 能直接从互联网访问吗？</h3><p>通常不能。它主要用于集群内部访问。浏览器实验通过 port-forward 建立临时通道。</p><h3 id="pod-替换后为什么不用修改-service" tabindex="-1"><a class="header-anchor" href="#pod-替换后为什么不用修改-service" aria-hidden="true">#</a> Pod 替换后为什么不用修改 Service？</h3><p>因为 Service 不写死 Pod IP，而是持续根据 Label 找到当前符合条件的 Pod。</p><h3 id="service-存在是否代表一定有应用可以处理请求" tabindex="-1"><a class="header-anchor" href="#service-存在是否代表一定有应用可以处理请求" aria-hidden="true">#</a> Service 存在是否代表一定有应用可以处理请求？</h3><p>不代表。Service 的 Endpoints 可能为空，所以还要检查它是否真正找到了可用 Pod。</p><h2 id="本课只记住五句话" tabindex="-1"><a class="header-anchor" href="#本课只记住五句话" aria-hidden="true">#</a> 本课只记住五句话</h2><ol><li>Pod IP 会随 Pod 替换而变化，不适合作为长期入口。</li><li>Service 为一组 Pod 提供稳定的集群内访问入口。</li><li>Service 通过 selector 匹配 Pod Label，而不是记住 Pod 名称。</li><li><code>port</code> 是 Service 端口，<code>targetPort</code> 是 Pod 应用端口。</li><li>Service 存在不等于后端存在，要用 describe 检查 Endpoints。</li></ol><h2 id="下一课预告" tabindex="-1"><a class="header-anchor" href="#下一课预告" aria-hidden="true">#</a> 下一课预告</h2><p>下一课专门制造一次 Service 无法访问的故障：故意把 selector 写错。你会看到 Pod 全部 Running，但 Service 的 Endpoints 为空，并学会沿“Service → Label → Pod”这条链定位问题。</p>`,168),l=[d];function r(c,t){return a(),n("div",null,l)}const o=e(i,[["render",r],["__file","10-第九课-Service稳定访问入口.html.vue"]]);export{o as default};
